import { useState, useEffect, useRef } from 'react';
import { motion, useScroll, useTransform } from 'framer-motion';
import { Calendar, User, ArrowLeft, Tag } from 'lucide-react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import PageLayout from '@/components/layout/PageLayout';
import { getBlogBySlug, getRelatedBlogs, type Blog } from '@/data/blogs-supabase';
import { Helmet } from 'react-helmet-async';

const BlogDetail = () => {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [blog, setBlog] = useState<Blog | null>(null);
  const [relatedBlogs, setRelatedBlogs] = useState<Blog[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  const heroRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: heroRef,
    offset: ["start start", "end start"]
  });
  
  const imageY = useTransform(scrollYProgress, [0, 1], ['0%', '50%']);
  const imageOpacity = useTransform(scrollYProgress, [0, 0.5, 1], [1, 0.8, 0.5]);

  useEffect(() => {
    if (slug) {
      loadBlog(slug);
    }
  }, [slug]);

  const loadBlog = async (slug: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const fetchedBlog = await getBlogBySlug(slug);
      if (!fetchedBlog) {
        setError('Blog post not found');
        return;
      }
      setBlog(fetchedBlog);
      
      // Load related blogs
      if (fetchedBlog.tags && fetchedBlog.tags.length > 0) {
        const related = await getRelatedBlogs(fetchedBlog.id, fetchedBlog.tags, 3);
        setRelatedBlogs(related);
      }
    } catch (err) {
      console.error('Error loading blog:', err);
      setError('Failed to load blog post');
    } finally {
      setIsLoading(false);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) return 'No date';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  };

  if (isLoading) {
    return (
      <PageLayout showFooter={false}>
        <div className="min-h-screen bg-gradient-to-br from-black via-gray-900 to-black flex items-center justify-center">
          <div className="text-white text-xl">Loading...</div>
        </div>
      </PageLayout>
    );
  }

  if (error || !blog) {
    return (
      <PageLayout showFooter={false}>
        <div className="relative min-h-screen">
          <div className="fixed inset-0 -z-10 bg-gradient-to-br from-black via-gray-900 to-black" />
          <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-16">
            <div className="blog-glass rounded-lg p-8 text-center">
              <p className="text-red-400 mb-4">{error || 'Blog post not found'}</p>
              <button
                onClick={() => navigate('/blog')}
                className="px-6 py-3 bg-white/10 border border-white/20 rounded-lg text-white hover:bg-white/20 transition-all"
              >
                Back to Blog
              </button>
            </div>
          </div>
        </div>
      </PageLayout>
    );
  }

  return (
    <>
      <Helmet>
        <title>{blog.seo_title || blog.title} | Origins Radio Blog</title>
        <meta name="description" content={blog.seo_description || blog.excerpt || blog.title} />
      </Helmet>
      
      <PageLayout showFooter={false}>
        <div className="min-h-screen bg-black blog-detail-scroll">
          {/* Fixed Back Button */}
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            className="fixed top-24 left-4 md:left-8 z-50"
          >
            <Link
              to="/blog"
              className="inline-flex items-center gap-2 px-4 py-2 bg-black/60 backdrop-blur-md border border-white/20 rounded-full text-white hover:bg-white/10 transition-all"
            >
              <ArrowLeft className="w-5 h-5" />
              <span className="hidden md:inline">Back</span>
            </Link>
          </motion.div>

          {/* Hero Section with Parallax */}
          {blog.cover_image_url && (
            <div ref={heroRef} className="relative h-[70vh] overflow-hidden">
              <motion.div
                className="absolute inset-0"
                style={{ y: imageY, opacity: imageOpacity }}
              >
                <img
                  src={blog.cover_image_url}
                  alt={blog.title}
                  className="w-full h-full object-cover scale-110"
                />
              </motion.div>
              <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/30 to-black" />
            </div>
          )}

          {/* Content Section */}
          <div className="relative -mt-32 z-10">
            <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
              {/* Article Card */}
              <motion.article
                initial={{ opacity: 0, y: 40 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8, delay: 0.2 }}
                className="blog-glass rounded-2xl shadow-2xl overflow-hidden mb-16"
              >
                <div className="p-8 md:p-12 lg:p-16">
                  {/* Featured Badge */}
                  {blog.featured && (
                    <motion.span
                      initial={{ opacity: 0, scale: 0.8 }}
                      animate={{ opacity: 1, scale: 1 }}
                      transition={{ delay: 0.4 }}
                      className="inline-block px-4 py-1.5 bg-gradient-to-r from-purple-500 to-pink-500 text-white text-xs font-bold rounded-full mb-6 uppercase tracking-wider"
                    >
                      Featured
                    </motion.span>
                  )}

                  {/* Title */}
                  <motion.h1
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.3 }}
                    className="text-4xl md:text-5xl lg:text-6xl font-bold text-white mb-8 font-newake leading-tight"
                  >
                    {blog.title}
                  </motion.h1>

                  {/* Meta Info */}
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 0.4 }}
                    className="flex flex-wrap items-center gap-6 text-gray-400 mb-10 pb-8 border-b border-white/10"
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">
                        <User className="w-5 h-5 text-white" />
                      </div>
                      <div>
                        <div className="text-xs text-gray-500 uppercase tracking-wide">Author</div>
                        <div className="text-white font-medium">{blog.author}</div>
                      </div>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center">
                        <Calendar className="w-5 h-5 text-gray-400" />
                      </div>
                      <div>
                        <div className="text-xs text-gray-500 uppercase tracking-wide">Published</div>
                        <div className="text-white font-medium">{formatDate(blog.published_at)}</div>
                      </div>
                    </div>
                  </motion.div>

                  {/* Content */}
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 0.5 }}
                    className="prose prose-invert prose-lg max-w-none mb-10"
                  >
                    <div className="text-gray-300 text-lg leading-relaxed whitespace-pre-wrap">
                      {blog.content}
                    </div>
                  </motion.div>

                  {/* Tags */}
                  {blog.tags && blog.tags.length > 0 && (
                    <motion.div
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.6 }}
                      className="flex flex-wrap items-center gap-3 pt-8 border-t border-white/10"
                    >
                      <div className="flex items-center gap-2 text-gray-400 mr-2">
                        <Tag className="w-5 h-5" />
                        <span className="text-sm font-medium">Tags:</span>
                      </div>
                      {blog.tags.map((tag, idx) => (
                        <span
                          key={idx}
                          className="px-4 py-2 bg-white/5 hover:bg-white/10 border border-white/10 text-gray-300 text-sm rounded-full transition-all cursor-pointer"
                        >
                          {tag}
                        </span>
                      ))}
                    </motion.div>
                  )}
                </div>
              </motion.article>

              {/* Related Posts */}
              {relatedBlogs.length > 0 && (
                <motion.div
                  initial={{ opacity: 0, y: 40 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.8, delay: 0.7 }}
                  className="mb-20"
                >
                  <h2 className="text-3xl md:text-4xl font-bold text-white mb-10 font-newake">
                    Related Stories
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {relatedBlogs.map((relatedBlog, idx) => (
                      <motion.div
                        key={relatedBlog.id}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: 0.8 + idx * 0.1 }}
                      >
                        <Link
                          to={`/blog/${relatedBlog.slug}`}
                          className="block blog-glass rounded-xl overflow-hidden hover:bg-white/10 transition-all group h-full"
                        >
                          {relatedBlog.cover_image_url && (
                            <div className="w-full h-48 overflow-hidden">
                              <img
                                src={relatedBlog.cover_image_url}
                                alt={relatedBlog.title}
                                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                              />
                            </div>
                          )}
                          <div className="p-6">
                            <h3 className="text-xl font-bold text-white mb-3 group-hover:text-gray-300 transition-colors line-clamp-2 font-newake">
                              {relatedBlog.title}
                            </h3>
                            {relatedBlog.excerpt && (
                              <p className="text-gray-400 text-sm line-clamp-3 leading-relaxed">
                                {relatedBlog.excerpt}
                              </p>
                            )}
                          </div>
                        </Link>
                      </motion.div>
                    ))}
                  </div>
                </motion.div>
              )}
            </div>
          </div>
        </div>
      </PageLayout>
    </>
  );
};

export default BlogDetail;

